/**
 * 도구별 사용 가이드 콘텐츠를 registry 메타에서 자동 생성.
 *
 * 목적:
 *   - long-tail 검색어 ("PDF 합치는 법", "이미지 압축 무료") 도달
 *   - HowTo JSON-LD 와 정합되는 실제 가이드 본문 제공
 *   - 사용자 평균 체류 시간 향상
 *
 * 카테고리별 표준 패턴:
 *   file-processing : Upload → Configure → Download
 *   generator       : Configure → Generate → Copy/Save
 *   text-analysis   : Input → Analyze → Copy/Save
 *
 * 도구별 한글 가이드 본문 + 공통 FAQ 를 반환. CSR 없이 server component
 * 에서 사용해 정적 HTML 에 박힌다.
 */

import type { ToolMeta } from '@/lib/tools/registry';

export type GuidePattern = 'file' | 'generator' | 'text' | 'calc' | 'viewer';

const GENERATOR_KEYS = new Set([
  'qr-code',
  'barcode',
  'color-palette',
  'uuid-gen',
  'password-gen',
  'lorem-ipsum',
  'totp',
  'rsa-keypair',
  'random-pick',
  // 오피스 생성기 (Configure → Generate → Save)
  'seal-stamp',
  'vcard-qr',
]);

/**
 * 값·날짜·단위를 입력칸에 넣어 결과를 계산·환산하는 도구.
 * "텍스트를 붙여넣으세요" 안내가 맞지 않으므로 별도 패턴으로 분리한다
 * (입력 → 계산 결과 → 복사).
 */
const CALC_KEYS = new Set([
  'age-calc',
  'dday',
  'timer-stopwatch',
  'percentage',
  'unit-converter',
  'color-converter',
  'timestamp-converter',
  'vat-calc',
  'salary-calc',
  'severance-calc',
  'leave-calc',
]);

/**
 * 파일을 열어 내용·정보를 읽기만 하는 뷰어/인스펙터.
 * 결과 파일을 "다운로드"하는 흐름이 아니므로 별도 패턴으로 분리한다
 * (파일 열기 → 보기 → 필요 시 내보내기).
 */
const VIEWER_KEYS = new Set([
  'epub-reader',
  'image-exif-view',
  'hwpx-viewer',
  'pdf-bookmarks',
  'pdf-stats',
  'epub-stats',
]);

const TEXT_ANALYSIS_KEYS = new Set([
  'text-diff',
  'text-count',
  'regex-tester',
  'jwt-decoder',
  'json-format',
  'base64',
  'cron-explainer',
  'markdown-stats',
  'url-parser',
  'url-encoder',
  'jsonpath',
  'sql-format',
  'html-entities',
  // 오피스 입력형 도구 (Input → Result → Copy)
  'redact',
  'excel-formula',
]);

export function getPattern(tool: ToolMeta): GuidePattern {
  if (GENERATOR_KEYS.has(tool.id)) return 'generator';
  if (CALC_KEYS.has(tool.id)) return 'calc';
  if (VIEWER_KEYS.has(tool.id)) return 'viewer';
  if (TEXT_ANALYSIS_KEYS.has(tool.id)) return 'text';
  // text 카테고리 + 자체 입력형 도구는 대부분 text-analysis
  if (tool.category === 'text' || tool.category === 'dev' || tool.category === 'util') {
    // hash·file-hash 처럼 파일 입력 받는 일부는 file 패턴
    if (tool.id === 'file-hash') return 'file';
    return 'text';
  }
  return 'file';
}

export interface GuideStep {
  title: string;
  body: string;
}

export interface GuideContent {
  /** 메타 title (35자 이내) */
  metaTitle: string;
  /** 메타 description (150자 이내) */
  metaDescription: string;
  /** H1 + 도입 한 줄 요약 */
  intro: string;
  /** 핵심 기능 bullet 3~5개 */
  features: string[];
  /** 단계별 사용법 */
  steps: GuideStep[];
  /** 도구별 FAQ */
  faqs: Array<{ q: string; a: string }>;
}

/**
 * 도구별 맞춤 가이드 본문(override).
 *
 * 패턴 자동생성은 "어떤 도구에나 맞는" 일반 문장이라 long-tail SEO·체류시간에
 * 약하다. 검색 수요가 큰 도구는 여기에 실제 사용 시나리오·예시·함정을 담은
 * 도구별 본문을 작성해 자동생성 결과 위에 덮어쓴다.
 *
 * 지정한 필드만 교체되고, 생략한 필드는 자동생성 본문이 그대로 쓰인다.
 * `faqs` 를 주면 도구별 FAQ 가 먼저 오고 공통 FAQ(개인정보·무료·모바일)가
 * 뒤에 자동으로 붙는다.
 */
export interface GuideOverride {
  metaTitle?: string;
  metaDescription?: string;
  intro?: string;
  features?: string[];
  steps?: GuideStep[];
  /** 도구별 FAQ. 공통 FAQ 3종이 자동으로 뒤에 추가된다. */
  faqs?: Array<{ q: string; a: string }>;
}

/** 모든 패턴이 공유하는 공통 FAQ(개인정보·무료·모바일). */
