      '선행 0(예: 192.168.001.1)이나 255 초과 옥텟 같은 잘못된 주소를 즉시 오류로 잡아냅니다.',
      '각 결과 행마다 복사 버튼이 있어 방화벽·라우터 설정에 값을 바로 옮길 수 있습니다.',
