      '오류 복원 수준을 L(~7%)·M(~15%)·Q(~25%)·H(~30%)로 골라, 로고를 덮거나 인쇄가 닳아도 읽히는 여유를 둘 수 있습니다.',
      '전경색·배경색을 자유롭게 지정해 브랜드 색에 맞춘 QR 을 만듭니다(대비가 낮으면 인식률이 떨어지니 주의).',
      'QR 읽기 탭은 사진·스크린샷을 올리면 jsQR 로 내용을 해독하고, 결과가 http(s) 링크면 새 탭으로 바로 열 수 있습니다.',
      '생성·해독 모두 브라우저 안에서 처리돼 입력한 내용이 서버로 전송되지 않습니다.',
