  'video-convert': {
    metaTitle: '비디오 포맷 변환 (MP4·WebM·MOV·AVI·MKV) — 무료',
    metaDescription:
      'MP4·WebM·MOV·AVI·MKV 비디오 포맷을 브라우저에서 변환합니다. CRF 품질 조절(16~35), MP4=H.264/AAC, WebM=VP9/Opus, 폴더 일괄(ZIP). FFmpeg.wasm 기반이라 큰 파일은 느릴 수 있으며, 서버 전송 없는 무료 변환기.',
    intro:
      'MP4·WebM·MOV·AVI·MKV 다섯 컨테이너 사이로 비디오를 변환하는 도구입니다. 출력 포맷에 따라 코덱이 자동으로 정해집니다 — MP4·MOV·MKV 는 H.264+AAC, WebM 은 VP9+Opus, AVI 는 MPEG-4+MP3. CRF 슬라이더(16~35, 23 전후 표준)로 품질과 용량을 조절하고, 폴더 일괄 모드로 여러 영상을 같은 설정으로 변환해 ZIP 으로 받습니다. 모든 변환은 FFmpeg.wasm 으로 브라우저 안에서 처리됩니다.',
    features: [
      'MP4·WebM·MOV·AVI·MKV 다섯 포맷 사이를 변환하며, 포맷에 맞는 코덱(H.264/AAC·VP9/Opus 등)이 자동 적용됩니다.',
      'CRF 품질 슬라이더(16~35)로 화질·용량을 조절합니다. 낮을수록 고품질·큰 용량이고 23 전후가 표준입니다.',
      '변환 페이지 딥링크(?to=webm 등)로 들어오면 목표 포맷이 자동 선택됩니다.',
      '폴더 일괄 모드로 여러 영상을 같은 포맷·품질로 한꺼번에 변환해 ZIP 으로 내려받습니다.',
      '모든 변환이 브라우저 안 FFmpeg.wasm 으로 끝나 영상 파일이 서버로 전송되지 않습니다(최초 ~30MB 1회 다운로드).',
    ],
    steps: [
      {
        title: '비디오 업로드',
        body: '변환할 영상을 업로드하거나, 폴더 모드로 여러 영상을 한 번에 올립니다. 최초 1회 FFmpeg.wasm(~30MB)을 내려받아 캐시합니다. 미리보기와 해상도·길이가 표시됩니다.',
      },
      {
        title: '출력 포맷·품질 선택',
        body: 'MP4·WebM·MOV·AVI·MKV 중 목표 포맷을 고르고, CRF 슬라이더로 품질을 정합니다. 가장 널리 호환되는 건 MP4(H.264), 웹 업로드에 가벼운 건 WebM(VP9)입니다.',
      },
      {
        title: '변환·다운로드',
        body: '"변환" 을 누르면 진행률과 함께 재인코딩이 진행됩니다. 끝나면 결과 영상을 미리 본 뒤 다운로드하세요. 폴더 모드는 ZIP 으로 한꺼번에 받습니다.',
      },
    ],
    faqs: [
      {
        q: '변환이 왜 이렇게 느린가요?',
        a: '이 도구는 영상을 서버가 아닌 브라우저 안의 FFmpeg.wasm 으로 재인코딩하기 때문입니다. WebAssembly 는 네이티브 프로그램보다 느리고, 영상의 모든 프레임을 다시 압축하므로 길이·해상도가 클수록 오래 걸립니다. 또 처음 한 번은 FFmpeg.wasm(~30MB) 다운로드가 더해집니다. 대신 영상이 외부로 전송되지 않아 안전합니다.',
      },
      {
        q: '포맷마다 어떤 코덱으로 변환되나요?',
        a: 'MP4·MOV·MKV 는 H.264 비디오 + AAC 오디오, WebM 은 VP9 + Opus, AVI 는 호환성을 위해 MPEG-4 + MP3 로 인코딩됩니다. 즉 같은 .mkv 라도 컨테이너만 바뀌는 게 아니라 내부 스트림이 H.264/AAC 로 재인코딩됩니다. 호환성이 가장 좋은 선택은 MP4 입니다.',
      },
      {
        q: '아주 큰 영상도 변환할 수 있나요?',
        a: '브라우저 메모리 안에서 처리하므로 매우 큰 파일(수백 MB~GB)은 메모리 부족으로 실패하거나 매우 느릴 수 있습니다. 큰 영상은 먼저 비디오 압축·자르기로 용량·길이를 줄인 뒤 변환하면 안정적입니다. 모바일은 데스크톱보다 한계가 낮습니다.',
      },
    ],
  },

