  'gif-optimize': {
    metaTitle: 'GIF 용량 최적화 (색·해상도·프레임 줄이기) — 무료',
    metaDescription:
      'GIF 용량을 브라우저에서 줄입니다. 약하게/보통/강하게 프리셋, 색 수(최대 256→64)·해상도·프레임률 조절, 2-pass 팔레트. FFmpeg.wasm 기반, 서버 전송 없는 무료 GIF 압축 도구.',
    intro:
      '이미 만들어진 GIF 의 용량을 줄이는 도구입니다. 약하게(256색)·보통(128색·80% 크기)·강하게(64색·10fps·60% 크기) 프리셋과 함께, 색 수·해상도(%)·프레임률을 직접 조절할 수 있습니다. GIF 용량은 대부분 색 수·픽셀 수·프레임 수에 비례하므로, 이 셋을 낮추면 용량이 크게 떨어집니다. 2-pass 팔레트(diff 모드)로 줄인 색 안에서도 화질을 최대한 보존합니다. 모든 처리는 FFmpeg.wasm 으로 브라우저 안에서 이뤄집니다.',
    features: [
      '약하게·보통·강하게 3가지 프리셋으로 색·해상도·프레임률을 한 번에 조절해 빠르게 압축합니다.',
      '색 수(최대 256~64), 해상도(%), 프레임률을 직접 조절해 용량과 화질의 균형을 세밀하게 맞춥니다.',
      'palettegen 의 diff 모드 + reserve_transparent 로 투명 영역과 화질을 지키며 색을 줄입니다.',
      '원본 대비 감소율(예: -58%)을 결과에 표시해 압축 효과를 바로 확인합니다.',
      '모든 처리가 브라우저 안 FFmpeg.wasm 으로 끝나 GIF 파일이 서버로 전송되지 않습니다.',
    ],
    steps: [
      {
        title: 'GIF 업로드',
        body: '용량을 줄일 GIF 파일을 올립니다. 최초 1회 FFmpeg.wasm(~30MB)을 내려받습니다.',
      },
      {
        title: '프리셋·세부 조절',
        body: '"보통" 으로 시작해 보고, 더 줄여야 하면 "강하게" 를 누르거나 색 수·해상도·프레임률을 직접 낮춥니다. 화질을 지키려면 색 수는 그대로 두고 해상도만 약간 낮추는 것이 효과적입니다.',
      },
      {
        title: '최적화·다운로드',
        body: '"최적화" 를 누르면 팔레트 생성→인코딩 후 결과가 나옵니다. 감소율과 화질을 확인하고, 부족하면 설정을 조절해 다시 시도한 뒤 다운로드하세요.',
      },
    ],
    faqs: [
      {
        q: '용량을 가장 효과적으로 줄이는 방법은?',
        a: 'GIF 용량은 색 수 × 해상도(픽셀 수) × 프레임 수 에 비례합니다. 화질 영향이 가장 적으면서 용량을 크게 줄이는 순서는 보통 ① 해상도 축소(예: 80%) → ② 색 수 감소(256→128) → ③ 프레임률 낮추기 입니다. 셋을 조금씩 조합하면 화질을 크게 해치지 않고도 절반 이하로 줄일 수 있습니다. "강하게" 프리셋이 이 셋을 모두 적용합니다.',
      },
      {
        q: '색을 줄이면 화면이 얼룩덜룩해져요.',
        a: '색 수를 64처럼 크게 낮추면 그라데이션·사진 계열 GIF 에서 색 띠(밴딩)나 얼룩이 생길 수 있습니다. 이 도구는 디더링으로 이를 완화하지만, 색이 풍부한 GIF 라면 색 수를 128 이상으로 유지하고 대신 해상도를 낮추는 편이 깔끔합니다. 색이 단순한 일러스트·아이콘은 64색으로도 잘 나옵니다.',
      },
      {
        q: '투명 배경이 깨지지 않나요?',
        a: '팔레트 생성 시 reserve_transparent 옵션으로 투명색 한 칸을 비워 두고, paletteuse 의 alpha_threshold 로 투명/불투명을 판정합니다. 덕분에 투명 배경 GIF 도 대체로 잘 보존됩니다. 다만 반투명(부분 투명) 픽셀은 GIF 포맷 자체가 지원하지 않아 완전 투명 또는 불투명으로 처리됩니다.',
      },
    ],
  },

