  'css-gradient': {
    metaTitle: 'CSS 그라디언트 생성기 (linear·radial) — 무료 온라인',
    metaDescription:
      'CSS linear·radial 그라디언트를 시각적으로 만듭니다. 각도 조절, 색상 stop 추가·위치 지정, 실시간 미리보기, background 코드 복사. 브라우저에서 처리되는 무료 CSS gradient 생성기.',
    intro:
      'CSS linear-gradient·radial-gradient 를 시각적으로 만들고 코드를 바로 복사하는 도구입니다. 선형(linear)은 각도(deg)를, 원형(radial)은 가운데에서 퍼지는 형태를 만들고, 색상 stop 을 여러 개 추가해 각각 색과 위치(0~100%)를 지정합니다. 설정을 바꾸는 즉시 미리보기에 반영되고, background: linear-gradient(...) 형태의 CSS 코드가 함께 갱신됩니다. 버튼·배경·카드의 그라디언트를 빠르게 잡을 때 유용합니다.',
    features: [
      'linear(선형)·radial(원형) 두 방식을 지원하고, linear 는 각도(0~360deg)를 조절합니다.',
      '색상 stop 을 자유롭게 추가·삭제하고 각 stop 의 색과 위치(0~100%)를 지정해 다단계 그라디언트를 만듭니다.',
      '설정을 바꿀 때마다 미리보기와 background CSS 코드가 실시간으로 갱신됩니다.',
      'background: linear-gradient(...); 형태의 완성 코드를 복사 버튼으로 바로 가져갈 수 있습니다.',
    ],
    steps: [
      {
        title: '방식·각도 선택',
        body: 'linear(선형) 또는 radial(원형)을 고릅니다. linear 면 각도를 정하세요 — 90deg 는 왼→오, 0deg 는 아래→위, 180deg 는 위→아래 방향입니다.',
      },
      {
        title: '색상 stop 편집',
        body: '기본 두 색에서 시작해, "추가" 로 stop 을 넣고 각 색과 위치(%)를 조절합니다. 예를 들어 0%·50%·100% 에 서로 다른 색을 두면 3색 그라디언트가 됩니다.',
      },
      {
        title: '코드 복사',
        body: '미리보기에서 원하는 모양이 나오면 background CSS 코드를 복사해 스타일시트나 인라인 style 에 붙여 넣습니다.',
      },
    ],
    faqs: [
      {
        q: 'linear 와 radial 은 어떻게 다른가요?',
        a: 'linear-gradient 는 지정한 각도를 따라 색이 일직선으로 변하는 그라디언트입니다(예: 위에서 아래로). radial-gradient 는 중심점에서 바깥으로 원형으로 퍼지며 색이 변합니다 — 스포트라이트·버블 같은 느낌을 낼 때 씁니다. 같은 색 조합이라도 둘의 인상이 꽤 다르니 미리보기로 비교해 보세요.',
      },
      {
        q: '각도(deg)는 어느 방향을 가리키나요?',
        a: 'CSS 그라디언트 각도는 "그라디언트가 향하는 방향" 을 시계 방향으로 잰 값입니다. 0deg 는 위쪽(아래→위로 색 변화), 90deg 는 오른쪽(왼→오), 180deg 는 아래쪽, 270deg 는 왼쪽입니다. 흔히 쓰는 "왼쪽 위 → 오른쪽 아래" 대각선은 135deg 입니다.',
      },
      {
        q: '색을 3개 이상 넣을 수 있나요?',
        a: '네. "추가" 버튼으로 색상 stop 을 원하는 만큼 넣고 각 위치(%)를 지정하면 됩니다. stop 들은 위치 순서대로 정렬되어 CSS 에 출력되므로, 같은 위치에 두 색을 두면 그 지점에서 색이 급격히 바뀌는 띠 효과(하드 스톱)도 만들 수 있습니다.',
      },
    ],
  },

